335	    CHECK(good.ok());
336	    CHECK(good.st.flags == (HYBRID_FLAG_RV64 | HYBRID_FLAG_L2C));
337	    CHECK(good.st.l2c.reg[HYBRID_L2C_OFF_CONTROL / 8] == 0x1);
338	    unlink(path);
339	  }
340	
341	  // a missing file is rejected (not a crash)
342	  CHECK(!read_state_file("/nonexistent/andesim-no-such-state").ok());
