// --runtime linux staging shared by fast and hybrid: manifest + stage the
// vlinux-run.elf that boots `app_elf` under the proxy kernel. On success
// returns the staged boot ELF and logs the one staged line; on failure prints
// "<ctx>: <why>" and returns "" (the caller's exit-2 path). `ctx` is each
// mode's full diagnostic prefix, passed verbatim -- they are asymmetric (fast
// says "--runtime linux", hybrid's early-fail prefix does not).
std::string stage_linux_boot(const std::string& app_elf, uint64_t mem_bytes,
                             const std::vector<std::string>& passthrough,
                             const char* ctx) {
  std::string stage_err;
  // U10d: ram_base 0 == the historical flat-from-zero guest map. Placing RAM
  // in AE350's high window (0x8_00000000) is U10e/U10f's switch, not this
  // plumbing change.
  const std::string boot_elf =
      stage_linux_runtime(app_elf, mem_bytes, /*ram_base=*/0, passthrough,
