// Hybrid mode: the mmap window is the only RAM. When the driver places it
// at the high base (--mem-size past the low window), the low 2 GiB window
// aliases the mmap's first 2 GiB -- the app image and vlinux are linked
// low and the core fetches them through this view, mirroring QEMU AE350's
// DRAM/DRAM_ALIAS pair. SimpleMemory subtracts each region's own base, so
// both views land on the same mmap offsets.
const MemoryRegion ram_region = shared_ram
  ? MemoryRegion{args.shared_mem_base,
                 args.shared_mem_base + args.shared_mem_size - 1}
  : MemoryRegion{RAM_BASE, RAM_END};
constexpr uint64_t kLowWindowBytes = 2ULL * 1024 * 1024 * 1024;
const MemoryRegion ram_alias_region = shared_ram
  ? (args.shared_mem_base != 0
       ? MemoryRegion{0, std::min<uint64_t>(kLowWindowBytes,
                                            args.shared_mem_size) - 1}
       : MemoryRegion{SimpleMemory<32>::INVALID_ADDRESS,
                      SimpleMemory<32>::INVALID_ADDRESS})
  : MemoryRegion{RAM_ALIAS_BASE, RAM_ALIAS_END};

